import torch
from torch import Tensor
from torch.library import Library, impl

my_lib = Library("mylib", "DEF")
my_lib.define("my_gemm(Tensor a, Tensor b) -> Tensor")

@impl(my_lib, "my_gemm", "CUDA")
def my_gemm_cuda(a: Tensor, b: Tensor) -> Tensor:
    # Real GEMM launched here (details omitted)
    return torch.matmul(a, b)

@impl(my_lib, "my_gemm", "Meta")
def my_gemm_meta(a: Tensor, b: Tensor) -> Tensor:
    # Returns a fake tensor with the correct output shape/dtype; no data
    return torch.empty(a.shape[0], b.shape[1], dtype=a.dtype, device="meta")

@torch.compile
def f(x, w):
    return torch.ops.mylib.my_gemm(x, w)
